auto button = Gtk::Button();
button.set_label("点击我（_C）");      // 下划线助记符：Alt+C 触发
button.set_use_underline(true);
button.set_icon_name("document-save"); // 或只显示图标
button.signal_clicked().connect([] {
  // 处理器：点击后执行
});

auto toggle = Gtk::ToggleButton();
toggle.set_label("切换我");
toggle.signal_toggled().connect([this] {
  if (toggle.get_active()) { /* 按下 */ } else { /* 弹起 */ }
});
